export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * Access information for datastore-based measurement (S3 ingestion).
 * Customers assume a uniquely provisioned IAM role to write usage records.
 * */
export class DatastoreAccessInformation {
    /**
     * Datastore platform. Defaults to `"s3"`.
     * @example "s3"
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores | string;

    /**
     * Customer AWS account ID trusted to assume the ingestion role.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * IAM role ARN provisioned for this measurement (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * External ID required to assume the ingestion role (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * S3 URI prefix for usage ingestion (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * S3 URI prefix for the dead-letter queue (generated).
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    /**
     * AWS region for the ingestion buckets/role. Defaults to `"us-east-1"`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: Partial<DatastoreAccessInformation>) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                region,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.accountId = accountId;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
            this.region = region ? region : process.env.AWS_REGION || 'us-east-1';
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, iamRoleArn, externalId, ingestion, dlq, region } = datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
            if (region) influxPoint.tag('region', region);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        region,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            region,
            businessID,
            measurementId,
        });
    }

    private static buildTrustPolicy(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    private static buildInlinePolicy(businessID: string) {
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${businessID}/*`],
                },
                {
                    Sid: 'IngestionList',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
                {
                    Sid: 'DlqAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${dlqBucket}/${businessID}/*`],
                },
                {
                    Sid: 'DlqList',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
            ],
        };
    }

    private static roleName(businessID: string, measurementId: string) {
        return `datastore-${businessID}-${measurementId}`;
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { accountId, businessID, measurementId } = dbAccessInformation;
        const platform = dbAccessInformation.platform || SupportedDatastores.s3;
        const region = dbAccessInformation.region || process.env.AWS_REGION || 'us-east-1';

        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            throw new BadRequestException(`Unsupported datastore platform: ${platform}`);
        }
        if (!businessID || !measurementId) {
            throw new InternalServerErrorException('businessID and measurementId are required to setup datastore access');
        }
        if (!accountId) {
            throw new BadRequestException('accountId is required for datastoreBased measurement');
        }

        const externalId = dbAccessInformation.externalId || uuidv4();
        const roleName = DatastoreAccessInformation.roleName(businessID, measurementId);
        const iam = new IAMClient({ region });
        const sts = new STSClient({ region });

        try {
            const { Account: enterpriseAccountId } = await sts.send(new GetCallerIdentityCommand({}));
            const trustPolicy = DatastoreAccessInformation.buildTrustPolicy(accountId, externalId);

            let roleArn = dbAccessInformation.iamRoleArn;
            if (!roleArn) {
                const createResult = await iam.send(
                    new CreateRoleCommand({
                        RoleName: roleName,
                        AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                        Description: `Enterprise datastore ingestion role for business ${businessID} measurement ${measurementId}`,
                    })
                );
                roleArn = createResult.Role?.Arn || `arn:aws:iam::${enterpriseAccountId}:role/${roleName}`;

                await iam.send(
                    new PutRolePolicyCommand({
                        RoleName: roleName,
                        PolicyName: `${roleName}-policy`,
                        PolicyDocument: JSON.stringify(DatastoreAccessInformation.buildInlinePolicy(businessID)),
                    })
                );
            }

            const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
            const dlqBucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
            const ingestion = dbAccessInformation.ingestion || `s3://${ingestionBucket}/${businessID}/`;
            const dlq = dbAccessInformation.dlq || `s3://${dlqBucket}/${businessID}/`;

            return new DatastoreAccessInformation({
                platform: SupportedDatastores.s3,
                accountId,
                iamRoleArn: roleArn,
                externalId,
                ingestion,
                dlq,
                region,
                businessID,
                measurementId,
            });
        } catch (e) {
            if (e?.name === 'EntityAlreadyExistsException' || e?.Code === 'EntityAlreadyExists') {
                const existing = await iam.send(new GetRoleCommand({ RoleName: roleName }));
                const roleArn = existing.Role?.Arn;
                const externalIdExisting = dbAccessInformation.externalId || uuidv4();
                await iam.send(
                    new UpdateAssumeRolePolicyCommand({
                        RoleName: roleName,
                        PolicyDocument: JSON.stringify(
                            DatastoreAccessInformation.buildTrustPolicy(accountId, externalIdExisting)
                        ),
                    })
                );
                return new DatastoreAccessInformation({
                    platform: SupportedDatastores.s3,
                    accountId,
                    iamRoleArn: roleArn,
                    externalId: externalIdExisting,
                    ingestion:
                        dbAccessInformation.ingestion ||
                        `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/`,
                    dlq:
                        dbAccessInformation.dlq ||
                        `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/`,
                    region,
                    businessID,
                    measurementId,
                });
            }
            if (e?.name === 'MalformedPolicyDocumentException' || e?.Code === 'MalformedPolicyDocument') {
                throw new BadRequestException(`accountId: ${accountId} is invalid`);
            }
            throw e;
        }
    }

    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        previousConfiguration?: DatastoreAccessInformation
    ) {
        const platform = dbAccessInformation.platform || previousConfiguration?.platform || SupportedDatastores.s3;
        const region =
            dbAccessInformation.region || previousConfiguration?.region || process.env.AWS_REGION || 'us-east-1';
        const businessID = dbAccessInformation.businessID || previousConfiguration?.businessID;
        const measurementId = dbAccessInformation.measurementId || previousConfiguration?.measurementId;
        const accountId = dbAccessInformation.accountId || previousConfiguration?.accountId;
        const iamRoleArn = previousConfiguration?.iamRoleArn || dbAccessInformation.iamRoleArn;
        const externalId = previousConfiguration?.externalId || dbAccessInformation.externalId;
        const ingestion =
            previousConfiguration?.ingestion ||
            dbAccessInformation.ingestion ||
            `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/`;
        const dlq =
            previousConfiguration?.dlq ||
            dbAccessInformation.dlq ||
            `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/`;

        if (!iamRoleArn || !externalId) {
            return DatastoreAccessInformation.setupAccess(
                new DatastoreAccessInformation({
                    platform,
                    accountId,
                    region,
                    businessID,
                    measurementId,
                })
            );
        }

        if (accountId && accountId !== previousConfiguration?.accountId) {
            const roleName =
                iamRoleArn.split('/').pop() || DatastoreAccessInformation.roleName(businessID, measurementId);
            const iam = new IAMClient({ region });
            await iam.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(DatastoreAccessInformation.buildTrustPolicy(accountId, externalId)),
                })
            );
        }

        return new DatastoreAccessInformation({
            platform,
            accountId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            region,
            businessID,
            measurementId,
        });
    }
}

